    /// Initialize a new `
    #[doc = stringify!($invariant)]
    ///` with constant `k`. initial stored (tracked) value `v`,
    /// and in the namespace `ns`.

    pub axiom fn new(k: K, tracked v: V, ns: int) -> (tracked i: $invariant<K, V, Pred>)
        requires
            Pred::inv(k, v),
        ensures
            i.constant() == k,
            i.namespace() == ns;

